package com.quincaisoft.tenders.application;
import com.quincaisoft.tenders.api.TenderService;import com.quincaisoft.tenders.infrastructure.*;import com.quincaisoft.tenders.domain.TenderRules;
import com.quincaisoft.finance.api.FinanceService;import com.quincaisoft.sales.api.SalesService;import com.quincaisoft.customeraccounts.api.CustomerService;import com.quincaisoft.shared.*;
import jakarta.persistence.*;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;
import java.util.*;import java.time.*;import java.math.BigDecimal;import java.security.*;import java.nio.charset.StandardCharsets;import java.util.function.Supplier;
@Service public class DefaultTenderService implements TenderService {
 private final EntityManager em;private final ScopedTransactions tx;private final FinanceService finance;private final SalesService sales;private final CustomerService customers;private final JsonMapper json;
 public DefaultTenderService(EntityManager em,ScopedTransactions tx,FinanceService finance,SalesService sales,CustomerService customers,JsonMapper json){this.em=em;this.tx=tx;this.finance=finance;this.sales=sales;this.customers=customers;this.json=json;}
 private void reason(String s){if(s==null||s.trim().length()<3||s.length()>2000)throw new IllegalArgumentException("Reason of 3–2000 characters required");}
 private <T>T once(UUID op,String material,Class<T> type,Supplier<T> action){if(op==null)throw new IllegalArgumentException("Operation ID required");return tx.execute(()->{var s=TenantContext.current();String hash=hash(material);em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k",s.tenantId()+":"+op).getSingleResult();var rows=em.createNativeQuery("select request_hash,company_id,branch_id,response_json::text from idempotency_result where tenant_id=:t and operation_id=:o").setParameter("t",s.tenantId()).setParameter("o",op).getResultList();if(!rows.isEmpty()){Object[] r=(Object[])rows.getFirst();if(!hash.equals(r[0])||!s.companyId().equals(r[1])||!s.branchId().equals(r[2]))throw new IllegalStateException("Operation reused with another request or scope");if(r[3]==null)throw new IllegalStateException("Committed operation response expired; do not repeat");return json.readValue((String)r[3],type);}T result=action.get();em.flush();UUID id=result instanceof Fact f?f.id():((Session)result).id();em.createNativeQuery("insert into idempotency_result(tenant_id,operation_id,company_id,branch_id,request_hash,source_type,source_id,response_json) values(:t,:o,:c,:b,:h,'TENDER',:i,cast(:r as jsonb))").setParameter("t",s.tenantId()).setParameter("o",op).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("h",hash).setParameter("i",id).setParameter("r",json.writeValueAsString(result)).executeUpdate();em.createNativeQuery("insert into outbox_event(tenant_id,id,company_id,branch_id,operation_id,event_type,aggregate_type,aggregate_id,payload) values(:t,:i,:c,:b,:o,'TenderChanged.v1','tender',:a,cast(:p as jsonb))").setParameter("t",s.tenantId()).setParameter("i",UUID.randomUUID()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",op).setParameter("a",id).setParameter("p",json.writeValueAsString(result)).executeUpdate();return result;});}
 static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private CashSessionEntity session(UUID id){if(id==null)throw new IllegalArgumentException("Cash session required");var s=TenantContext.current();var r=em.find(CashSessionEntity.class,new CashSessionEntity.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null||!r.branchId.equals(s.branchId()))throw new NoSuchElementException("Cash session not found");return r;}
 private long expected(CashSessionEntity r){var raw=em.createNativeQuery("select coalesce(sum(cash_delta_xaf),0) from tender_fact where tenant_id=:t and company_id=:c and cash_session_id=:i").setParameter("t",r.tenantId).setParameter("c",r.companyId).setParameter("i",r.id).getSingleResult();return Math.addExact(r.openingXaf,new BigDecimal(raw.toString()).longValueExact());}
 private CashSessionEntity cash(UUID id,LocalDate date,long delta){var r=session(id);if(!"OPEN".equals(r.status)||!r.businessDate.equals(date))throw new IllegalStateException("Open cash session on the business date required");if(Math.addExact(expected(r),delta)<0)throw new IllegalArgumentException("Insufficient recorded till balance");if(delta!=0)r.activitySequence=Math.incrementExact(r.activitySequence);return r;}
 private Session view(CashSessionEntity r){return new Session(r.id,r.tillCode,r.businessDate,r.status,""+r.openingXaf,""+expected(r),r.countedXaf==null?null:r.countedXaf.toString(),r.version);}
 private Fact view(TenderFactEntity r){return new Fact(r.id,r.kind,r.customerId,r.saleId,r.depositId,r.cashSessionId,r.businessDate,""+r.amountXaf,""+r.cashDeltaXaf,r.journalId,r.reason);}
 private DepositView view(DepositBalanceEntity r){return new DepositView(r.id,r.customerId,""+r.originalXaf,""+r.allocatedXaf,""+r.refundedXaf,""+TenderRules.remaining(r.originalXaf,r.allocatedXaf,r.refundedXaf),r.version);}
 private DepositBalanceEntity depositBalance(UUID id){var s=TenantContext.current();var r=em.find(DepositBalanceEntity.class,new DepositBalanceEntity.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null||!r.branchId.equals(s.branchId()))throw new NoSuchElementException("Deposit not found");return r;}
 private void sale(UUID id,UUID customer){var r=sales.get(id);if(!"POSTED".equals(r.status())||!Objects.equals(r.customerId(),customer))throw new IllegalArgumentException("Posted sale for the same customer required");}
 public List<Session> sessions(){return tx.execute(()->em.createQuery("select r from CashSessionEntity r order by r.businessDate desc,r.id",CashSessionEntity.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 public List<Fact> facts(){return tx.execute(()->em.createQuery("select r from TenderFactEntity r order by r.businessDate desc,r.id",TenderFactEntity.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 public List<DepositView> deposits(){return tx.execute(()->em.createQuery("select r from DepositBalanceEntity r order by r.id",DepositBalanceEntity.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 public Session open(Open p){reason(p.reason());long opening=TenderRules.amount(p.openingXaf(),true);if(p.tillCode()==null||p.tillCode().isBlank()||p.tillCode().length()>80)throw new IllegalArgumentException("Till code required");return once(p.operationId(),"OPEN|"+p,Session.class,()->{finance.requireOpenPeriod(p.businessDate());var s=TenantContext.current();var r=new CashSessionEntity();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.actorId=s.actorId();r.tillCode=p.tillCode().trim();r.status="OPEN";r.businessDate=p.businessDate();r.openingXaf=opening;em.persist(r);em.flush();return view(r);});}
 public Session close(UUID id,Close p){reason(p.reason());long counted=TenderRules.amount(p.countedXaf(),true);return once(p.operationId(),"CLOSE|"+id+"|"+p,Session.class,()->{finance.requireOpenPeriod(p.businessDate());var r=cash(id,p.businessDate(),0);if(r.version!=p.version())throw new RevisionConflict("Cash session changed");long difference=Math.subtractExact(counted,expected(r));if(difference!=0){long n=Math.absExact(difference);fact(p.operationId(),"VARIANCE",null,null,null,id,p.businessDate(),n,difference,p.reason(),difference>0?entries("CASH_CONTROL","CASH_OVERAGE",n):entries("CASH_SHORTAGE","CASH_CONTROL",n));}r.countedXaf=counted;r.status="CLOSED";em.flush();return view(r);});}
 private List<FinanceService.Entry> entries(String debit,String credit,long n){return List.of(new FinanceService.Entry(debit,n,0),new FinanceService.Entry(credit,0,n));}
 private Fact fact(UUID op,String kind,UUID customer,UUID sale,UUID deposit,UUID session,LocalDate date,long amount,long delta,String reason,List<FinanceService.Entry> entries){var s=TenantContext.current();var r=new TenderFactEntity();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.operationId=op;r.actorId=s.actorId();r.kind=kind;r.customerId=customer;r.saleId=sale;r.depositId=deposit;r.cashSessionId=session;r.businessDate=date;r.amountXaf=amount;r.cashDeltaXaf=delta;r.reason=reason;r.journalId=finance.post(r.id,op,date,kind,entries);em.persist(r);em.flush();return view(r);}
 public Fact receipt(Receipt p){reason(p.reason());long n=TenderRules.amount(p.amountXaf(),false);return once(p.operationId(),"RECEIPT|"+p,Fact.class,()->{customers.requireEligible(p.customerId());sale(p.saleId(),p.customerId());finance.applyReceipt(p.saleId(),n);cash(p.cashSessionId(),p.businessDate(),n);return fact(p.operationId(),"RECEIPT",p.customerId(),p.saleId(),null,p.cashSessionId(),p.businessDate(),n,n,p.reason(),entries("CASH_CONTROL","ACCOUNTS_RECEIVABLE",n));});}
 public Fact deposit(Deposit p){reason(p.reason());long n=TenderRules.amount(p.amountXaf(),false);return once(p.operationId(),"DEPOSIT|"+p,Fact.class,()->{customers.requireEligible(p.customerId());cash(p.cashSessionId(),p.businessDate(),n);var s=TenantContext.current();var d=new DepositBalanceEntity();d.tenantId=s.tenantId();d.companyId=s.companyId();d.branchId=s.branchId();d.id=UUID.randomUUID();d.customerId=p.customerId();d.originalXaf=n;d.fundingKind="CASH";em.persist(d);em.flush();return fact(p.operationId(),"DEPOSIT",p.customerId(),null,d.id,p.cashSessionId(),p.businessDate(),n,n,p.reason(),entries("CASH_CONTROL","CUSTOMER_ADVANCES",n));});}
 public Fact allocate(UUID id,Allocation p){reason(p.reason());long n=TenderRules.amount(p.amountXaf(),false);return once(p.operationId(),"ALLOCATE|"+id+"|"+p,Fact.class,()->{var d=depositBalance(id);if(n>TenderRules.remaining(d.originalXaf,d.allocatedXaf,d.refundedXaf))throw new IllegalArgumentException("Allocation exceeds remaining deposit");sale(p.saleId(),d.customerId);finance.applyReceipt(p.saleId(),n);d.allocatedXaf=Math.addExact(d.allocatedXaf,n);return fact(p.operationId(),"ALLOCATION",d.customerId,p.saleId(),d.id,null,p.businessDate(),n,0,p.reason(),entries("CUSTOMER_ADVANCES","ACCOUNTS_RECEIVABLE",n));});}
 public Fact refund(UUID id,Allocation p){reason(p.reason());long n=TenderRules.amount(p.amountXaf(),false);return once(p.operationId(),"REFUND|"+id+"|"+p,Fact.class,()->{var d=depositBalance(id);if(!"CASH".equals(d.fundingKind))throw new IllegalStateException("Bank/provider deposit refunds require their verified refund workflow");if(n>TenderRules.remaining(d.originalXaf,d.allocatedXaf,d.refundedXaf))throw new IllegalArgumentException("Refund exceeds remaining deposit");cash(p.cashSessionId(),p.businessDate(),-n);d.refundedXaf=Math.addExact(d.refundedXaf,n);return fact(p.operationId(),"REFUND",d.customerId,null,d.id,p.cashSessionId(),p.businessDate(),n,-n,p.reason(),entries("CUSTOMER_ADVANCES","CASH_CONTROL",n));});}
 public Fact expense(CashExpense p){reason(p.reason());long n=TenderRules.amount(p.amountXaf(),false);if(p.expenseId()==null)throw new IllegalArgumentException("Approved expense identity required");return once(p.operationId(),"EXPENSE|"+p,Fact.class,()->{cash(p.cashSessionId(),p.businessDate(),-n);return fact(p.operationId(),"EXPENSE",null,null,null,p.cashSessionId(),p.businessDate(),n,-n,p.reason(),entries("OPERATING_EXPENSE","CASH_CONTROL",n));});}
 public Fact supplierDisbursement(SupplierCash p){reason(p.reason());long n=TenderRules.amount(p.amountXaf(),false);if(p.settlementId()==null||!Set.of("SUPPLIER_PAYMENT","SUPPLIER_ADVANCE").contains(p.kind()))throw new IllegalArgumentException("Supplier settlement source required");return once(p.operationId(),"SUPPLIER_CASH|"+p,Fact.class,()->{finance.requireOpenPeriod(p.businessDate());cash(p.cashSessionId(),p.businessDate(),-n);return fact(p.operationId(),p.kind(),null,null,null,p.cashSessionId(),p.businessDate(),n,-n,p.reason(),entries(p.kind().equals("SUPPLIER_PAYMENT")?"ACCOUNTS_PAYABLE":"SUPPLIER_ADVANCES","CASH_CONTROL",n));});}
}
